const defaults={user:{firstName:'Alex',lastName:'Martin',birth:'2009-03-14',className:'Première générale',bio:'J’apprends mieux avec des exemples concrets et des fiches courtes.'},subjects:[{id:'math',name:'Mathématiques',coef:5,color:'#5b83e3',note:'Les polynômes demandent davantage d’exemples.',tomorrow:true,today:false},{id:'fr',name:'Français',coef:5,color:'#e05c76',note:'Préparer l’EAF.',tomorrow:true,today:true},{id:'hist',name:'Histoire',coef:3,color:'#f1993a',note:'Retenir les dates avec des liens logiques.',tomorrow:false,today:false},{id:'eng',name:'Anglais',coef:3,color:'#34a66f',note:'Travailler le vocabulaire.',tomorrow:false,today:true},{id:'pc',name:'Physique-chimie',coef:4,color:'#8e63cf',note:'Difficultés avec les formules.',tomorrow:false,today:false}],grades:{math:[{id:1,name:'Polynômes',n:15,d:20,c:2,remark:'Bon raisonnement'},{id:2,name:'Fonctions',n:8,d:10,c:1,remark:''}],fr:[{id:3,name:'Commentaire',n:13,d:20,c:2,remark:'Soigner les transitions'}],hist:[{id:4,name:'Révolution française',n:16,d:20,c:1,remark:''}],eng:[{id:5,name:'Vocabulary',n:17,d:20,c:1,remark:''}],pc:[{id:6,name:'Mouvement',n:11,d:20,c:2,remark:''}]},coursePages:{math:['Polynômes du second degré\n\nForme développée : f(x) = ax² + bx + c\nDiscriminant : Δ = b² − 4ac\n\nSi Δ > 0, il existe deux racines réelles.'],fr:['La littérature d’idées\n\nDéfendre et entretenir la liberté.\nÉtienne de La Boétie, Discours de la servitude volontaire.'],hist:['La France en 1789\n\nLa monarchie est absolue : le roi détient quasiment tous les pouvoirs.\nLe pouvoir est héréditaire et la loi salique exclut les femmes de la succession.'],eng:['The NHS\n\nBefore 1948, Great Britain did not have a free healthcare system.'],pc:['Mouvement et vitesse\n\nv = d / t\nLa vitesse s’exprime en m/s dans le système international.']},schedule:[{day:0,h:8,subject:'math'},{day:0,h:9,subject:'math'},{day:0,h:10,subject:'fr'},{day:0,h:14,subject:'eng'},{day:1,h:9,subject:'hist'},{day:1,h:10,subject:'pc'},{day:1,h:11,subject:'fr'},{day:2,h:8,subject:'eng'},{day:2,h:10,subject:'math'},{day:3,h:8,subject:'fr'},{day:3,h:9,subject:'pc',alt:'hist'},{day:3,h:14,subject:'hist'},{day:4,h:9,subject:'math'},{day:4,h:11,subject:'eng'}],order:'custom',pageMode:'classic'};
let state=JSON.parse(localStorage.getItem('cahier-state')||'null')||structuredClone(defaults);let route='home',previous='home',selectedSubject=null,currentPage=0,editingSchedule=false,activeColor='#5b83e3';
const $=s=>document.querySelector(s), app=$('#app');
function save(){localStorage.setItem('cahier-state',JSON.stringify(state))}function icon(n){return {home:'⌂',courses:'▤',grades:'✦',schedule:'▦'}[n]}
function orderedSubjects(){let a=[...state.subjects];if(state.order==='alpha')a.sort((x,y)=>x.name.localeCompare(y.name));if(state.order==='coef')a.sort((x,y)=>y.coef-x.coef);return a}
function layout(content,title='',secondary=false){app.innerHTML=`<main class="shell"><header class="topbar"><div class="brand" onclick="go('home')"><span class="logo"></span><strong>Cahier</strong></div>${secondary?`<button class="btn" onclick="back()">← ${route==='notebook'?'Fermer le cahier':'Sortir'}</button>`:''}<div class="top-actions"><button class="icon-btn ia-btn" onclick="go('ai')">⭐ <span class="label">IA</span></button><button class="icon-btn plus" onclick="go('new-subject')">+</button><button class="icon-btn" onclick="go('settings')">⚙️ <span class="label">Paramètres</span></button></div></header><section class="page-frame">${title?`<h1 class="page-title">${title}</h1>`:''}${content}</section>${['home','courses','grades','schedule'].includes(route)?bottomNav():''}</main>`}
function bottomNav(){return `<nav class="bottom-nav">${[['home','Accueil'],['courses','Cours'],['grades','Notes'],['schedule','Emploi du temps']].map(([r,l])=>`<button class="nav-btn ${route===r?'active':''}" onclick="go('${r}')"><span>${icon(r)}</span>${l}</button>`).join('')}</nav>`}
function go(r,data){previous=route;if(data)selectedSubject=data;route=r;render();scrollTo(0,0)}function back(){route=previous==='notebook'?'courses':previous;render()}
function render(){({home, courses, grades, schedule, ai, settings, 'new-subject':newSubject, notebook}[route]||home)()}
function home(){layout(`<div class="hero"><span class="section-kicker">Vendredi 12 septembre</span><h1>Salut ${state.user.firstName} !</h1><p>Voici l’essentiel pour bien démarrer demain.</p></div><section class="tomorrow"><div class="section-kicker">À retenir pour demain</div><div class="memo-grid"><article class="memo" style="--c:#5b83e3"><div class="subject">Mathématiques</div><p>Pour le discriminant, pense : <b>« b² moins quatre a c »</b>. Son signe te donne immédiatement le nombre de racines.</p></article><article class="memo" style="--c:#e05c76"><div class="subject">Français</div><p>La Boétie pose une idée clé : un pouvoir ne tient que parce que le peuple accepte de lui obéir.</p></article><article class="memo" style="--c:#34a66f"><div class="subject">Petit défi</div><p>Explique chaque notion à voix haute en une minute : si les mots viennent simplement, c’est gagné.</p></article></div><div class="tip">💡 <b>Conseil :</b> commence par 15 minutes de maths, puis relis ton introduction de français. Une petite révision régulière vaut mieux qu’une longue session.</div></section>`,'Accueil')}
function badge(s){return `${s.today?'<span class="today-dot">Aujourd’hui</span>':''}`}
function courses(){layout(`<div class="toolbar-row"><p>Ouvre une matière : tu retrouveras directement ta dernière page.</p><span class="spacer"></span><button class="btn primary" onclick="go('new-subject')">+ Nouvelle matière</button></div><div class="subjects">${orderedSubjects().map(s=>`<article class="subject-card ${s.tomorrow?'tomorrow-subject':''}" style="--c:${s.color}" onclick="openBook('${s.id}')"><div><div class="subject-name">${s.name}</div><div class="meta">${(state.coursePages[s.id]||[]).length} page(s) · coefficient ${s.coef}${s.tomorrow?' · À relire pour demain':''}</div></div>${badge(s)}</article>`).join('')}</div>`,'Cours')}
function avg(id){let g=state.grades[id]||[];if(!g.length)return null;return g.reduce((a,x)=>a+(x.n/x.d*20)*x.c,0)/g.reduce((a,x)=>a+x.c,0)}function general(){let sum=0,c=0;state.subjects.forEach(s=>{let a=avg(s.id);if(a!==null){sum+=a*s.coef;c+=s.coef}});return c?sum/c:0}
function grades(){layout(`<div class="toolbar-row"><div class="average">Moyenne générale : ${general().toFixed(1)}/20</div><span class="spacer"></span><button class="btn primary" onclick="go('new-subject')">+ Nouvelle matière</button></div>${orderedSubjects().map(s=>`<section class="panel ${s.tomorrow?'tomorrow-subject':''}" style="border-left:9px solid ${s.color}"><div class="row"><h2 style="margin:0">${s.name} — ${avg(s.id)?.toFixed(1)||'—'}/20</h2><span class="spacer"></span><b>Coeff. ${s.coef}</b> ${badge(s)} <button class="btn" onclick="gradeModal('${s.id}')">+</button></div>${(state.grades[s.id]||[]).map(g=>`<div class="grade-line"><span><b>${g.name}</b>${g.remark?` · ${g.remark}`:''}</span><span>${g.n}/${g.d}${g.d!==20?` (${(g.n/g.d*20).toFixed(1)}/20)`:''} · coeff. ${g.c}</span><span class="grade-actions"><button class="tiny-action" onclick="gradeModal('${s.id}',${g.id})">✏️</button> <button class="tiny-action" onclick="deleteGrade('${s.id}',${g.id})">🗑️</button></span></div>`).join('')||'<p class="meta">Aucune note.</p>'}</section>`).join('')}`,'Notes')}
function newSubject(){layout(`<form id="subjectForm"><div class="colors">${['#5b83e3','#e05c76','#f1993a','#34a66f','#8e63cf','#e4bf2d'].map((c,i)=>`<button type="button" aria-label="Choisir cette couleur" class="color-dot ${i===0?'selected':''}" style="--c:${c}" onclick="chooseColor(this,'${c}')"></button>`).join('')}</div><div class="field"><label>Nom de la matière</label><input name="name" required placeholder="Ex. Sciences économiques et sociales"></div><div class="field"><label>Coefficient</label><input name="coef" required type="number" min="1" max="20" value="1"></div><div class="field"><label>Remarque facultative</label><textarea name="note" placeholder="Une difficulté, un objectif ou une information utile pour l’IA…"></textarea></div><div class="form-actions"><button type="button" class="btn danger" onclick="back()">❌ Annuler</button><button class="btn primary">✓ Valider</button></div></form>`,'Nouvelle matière',true);$('#subjectForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),id='s'+Date.now();state.subjects.push({id,name:f.get('name'),coef:+f.get('coef'),note:f.get('note'),color:activeColor,tomorrow:false,today:false});state.grades[id]=[];state.coursePages[id]=[''];save();route='courses';render();toast('Matière ajoutée')};}
function chooseColor(el,c){activeColor=c;document.querySelectorAll('.color-dot').forEach(x=>x.classList.remove('selected'));el.classList.add('selected')}
function gradeModal(id,gid){let s=state.subjects.find(x=>x.id===id),g=(state.grades[id]||[]).find(x=>x.id===gid);modal(`<h2>${g?'Modifier':'Nouvelle'} note en ${s.name}</h2><form id="gradeForm"><div class="field"><label>Nom</label><input name="name" required value="${g?.name||''}"></div><div class="row"><div class="field"><label>Note</label><input name="n" type="number" step=".25" required value="${g?.n||''}"></div><b>/</b><div class="field"><label>Barème</label><input name="d" type="number" required value="${g?.d||20}"></div></div><div class="field"><label>Coefficient</label><input name="c" type="number" min=".5" step=".5" value="${g?.c||1}"></div><div class="field"><label>Remarque</label><textarea name="remark">${g?.remark||''}</textarea></div><div class="form-actions"><button type="button" class="btn" onclick="closeModal()">❌ Annuler</button><button class="btn primary">✓ Valider</button></div></form>`);$('#gradeForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),v={id:g?.id||Date.now(),name:f.get('name'),n:+f.get('n'),d:+f.get('d'),c:+f.get('c'),remark:f.get('remark')};if(g)Object.assign(g,v);else state.grades[id].push(v);save();closeModal();render();toast('Note enregistrée')}}
function deleteGrade(id,gid){if(confirm('Supprimer cette note ?')){state.grades[id]=state.grades[id].filter(x=>x.id!==gid);save();render()}}
function schedule(){let days=['Lundi','Mardi','Mercredi','Jeudi','Vendredi'];let weekend=state.schedule.some(x=>x.day>4);if(weekend)days.push('Samedi','Dimanche');let used=state.schedule.map(x=>x.h),start=editingSchedule?8:Math.min(...used),end=editingSchedule?19:Math.max(...used);let cells=`<div class="day-head"></div>${days.map(d=>`<div class="day-head">${d}</div>`).join('')}`;for(let h=start;h<=end;h++){cells+=`<div class="time">${h}h</div>`;days.forEach((d,day)=>{let x=state.schedule.find(z=>z.day===day&&z.h===h),s=x&&state.subjects.find(z=>z.id===x.subject),s2=x?.alt&&state.subjects.find(z=>z.id===x.alt);cells+=`<div class="slot ${x?'filled':''} ${x?.alt?'split':''} ${editingSchedule?'editing':''}" style="--c:${s?.color||'#fff'};--c2:${s2?.color||'#fff'}" onclick="${editingSchedule?`slotModal(${day},${h})`:''}">${x?(s2?`<small>Semaine A</small> ${s.name}<br><small>Semaine B</small> ${s2.name}`:s.name):editingSchedule?'<span class="meta">＋</span>':''}</div>`})}layout(`<div class="toolbar-row"><p>${editingSchedule?'Sélectionne une case, vide ou remplie, pour la modifier.':'Les créneaux vides sont masqués en mode lecture.'}</p><span class="spacer"></span><button class="btn primary" onclick="toggleSchedule()">${editingSchedule?'✓ Valider':'✏️ Modifier'}</button></div><div class="schedule-wrap"><div class="schedule" style="--days:${days.length}">${cells}</div></div>`,'Emploi du temps')}
function toggleSchedule(){editingSchedule=!editingSchedule;render();if(!editingSchedule){save();toast('Emploi du temps enregistré')}}
function slotModal(day,h){let x=state.schedule.find(z=>z.day===day&&z.h===h);let opts=state.subjects.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');modal(`<h2>${x?'Modifier':'Ajouter'} le cours de ${h}h</h2><div class="field"><label>Semaine A</label><select id="slotA"><option value="">Aucun</option>${opts}</select></div><div class="field"><label>Semaine B (facultatif)</label><select id="slotB"><option value="">Identique à la semaine A</option>${opts}</select></div><div class="form-actions"><button class="btn danger" onclick="removeSlot(${day},${h})">Supprimer</button><button class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" onclick="saveSlot(${day},${h})">Valider</button></div>`);$('#slotA').value=x?.subject||'';$('#slotB').value=x?.alt||''}
function saveSlot(day,h){let a=$('#slotA').value,b=$('#slotB').value;state.schedule=state.schedule.filter(x=>!(x.day===day&&x.h===h));if(a)state.schedule.push({day,h,subject:a,alt:b||undefined});closeModal();render()}function removeSlot(day,h){state.schedule=state.schedule.filter(x=>!(x.day===day&&x.h===h));closeModal();render()}
function openBook(id){selectedSubject=id;let pages=state.coursePages[id]||[''];currentPage=pages.length-1;previous='courses';route='notebook';render()}
function notebook(){let s=state.subjects.find(x=>x.id===selectedSubject),pages=state.coursePages[s.id]||[''];layout(`<div class="notebook-frame"><div class="notebook-top"><button class="tool" onclick="cmd('bold')"><b>B</b></button><button class="tool" onclick="cmd('italic')"><i>I</i></button><button class="tool" onclick="cmd('underline')"><u>U</u></button><select class="tool" onchange="cmd('fontName',this.value)"><option>DM Sans</option><option>Georgia</option><option>Kalam</option></select><input title="Couleur du texte" type="color" class="tool" onchange="cmd('foreColor',this.value)"><input title="Surligner" type="color" class="tool" value="#fff09b" onchange="cmd('hiliteColor',this.value)"><button class="tool" onclick="cmd('justifyLeft')">≡</button><button class="tool" onclick="cmd('justifyCenter')">≡↔</button><button class="tool" onclick="cmd('justifyRight')">≡→</button><button class="tool" onclick="drawNotice('crayon')">✏️</button><button class="tool" onclick="drawNotice('gomme')">⌫</button><button class="tool" onclick="$('#photoInput').click()">📎 Photo</button><button class="tool" onclick="togglePageMode()">${state.pageMode==='classic'?'Page classique':'Page infinie'}</button></div><div id="paper" class="notebook-page ${state.pageMode==='infinite'?'infinite':''}" contenteditable="true" spellcheck="true" oninput="savePage()">${pages[currentPage]||''}<span class="page-no">${currentPage+1}</span></div><div class="page-controls"><button class="btn" onclick="turn(-1)">←</button><button class="btn" onclick="jumpPage()">Page ${currentPage+1} / ${pages.length}</button><button class="btn" onclick="turn(1)">→</button><button class="btn" onclick="addPage()">+ Page</button><button class="btn danger" onclick="deletePage()">🗑️</button></div></div>`,s.name,true);setTimeout(()=>{$('#photoInput').onchange=addPhoto},0)}
function cleanPaper(){let c=$('#paper').cloneNode(true);c.querySelector('.page-no')?.remove();return c.innerHTML}function savePage(){state.coursePages[selectedSubject][currentPage]=cleanPaper();save()}function cmd(c,v){document.execCommand(c,false,v);$('#paper').focus();savePage()}function turn(n){savePage();let p=state.coursePages[selectedSubject];let t=currentPage+n;if(t<0)return;if(t>=p.length)p.push('');currentPage=t;render();$('#paper').classList.add('flip')}function addPage(){savePage();state.coursePages[selectedSubject].push('');currentPage=state.coursePages[selectedSubject].length-1;save();render()}function deletePage(){let p=state.coursePages[selectedSubject];if(p.length===1)p[0]='';else p.splice(currentPage,1);currentPage=Math.max(0,currentPage-1);save();render()}function jumpPage(){let p=prompt('Numéro de page');if(p&&+p<=state.coursePages[selectedSubject].length){savePage();currentPage=+p-1;render()}}function togglePageMode(){state.pageMode=state.pageMode==='classic'?'infinite':'classic';save();render()}function drawNotice(t){toast(`${t==='crayon'?'Crayon':'Gomme'} sélectionné — dessinez directement sur un écran tactile`)}function addPhoto(e){let f=e.target.files[0];if(!f)return;let r=new FileReader;r.onload=()=>{document.execCommand('insertHTML',false,`<img src="${r.result}" style="max-width:55%;cursor:move;border-radius:8px" ondblclick="this.requestFullscreen?.()">`);savePage()};r.readAsDataURL(f)}
function ai(){layout(`<div class="chat-layout"><aside class="chat-list"><button class="btn primary" onclick="newChat()">+ Nouveau chat</button><div class="chat-item active">Réviser les polynômes</div><div class="chat-item">Préparation EAF</div><div class="chat-item">Questions de physique</div></aside><section class="chat-main"><div class="messages" id="messages"><div class="bubble ai">Bonjour ${state.user.firstName} ! Je peux utiliser tes cours et tes remarques pour t’expliquer une notion, créer un QCM ou préparer une évaluation. Tu peux aussi m’envoyer une photo.</div><div class="bubble user">Aide-moi à retenir le discriminant.</div><div class="bubble ai">Dans ton cahier de maths, la formule est <b>Δ = b² − 4ac</b>. Ton mémo : <b>« b au carré, moins quatre a c »</b>. Veux-tu un mini-QCM de 5 questions ?</div></div><div class="chat-compose"><button class="icon-btn" onclick="toast('Ajoute une photo de cours à analyser')">📎</button><input id="aiInput" class="chat-input" placeholder="Pose une question sur tes cours…"><button class="btn primary" onclick="askAI()">Envoyer</button></div></section></div>`,'IA',true);$('#aiInput').onkeydown=e=>{if(e.key==='Enter')askAI()}}
function askAI(){let i=$('#aiInput');if(!i.value.trim())return;let m=$('#messages');m.insertAdjacentHTML('beforeend',`<div class="bubble user">${i.value}</div><div class="bubble ai">Je peux t’aider avec ce point. Dans cette démonstration, je m’appuie sur tes cours enregistrés et tes difficultés. Pour une réponse IA réelle et l’analyse d’images, il faudra connecter le service IA lors de la mise en production.</div>`);i.value='';m.scrollTop=m.scrollHeight}
function newChat(){toast('Nouveau chat créé')}
function settings(){layout(`<div class="settings-grid"><article class="setting-card" onclick="orderModal()"><h3>↕ Ordre des matières</h3><p>${state.order==='alpha'?'Alphabétique':state.order==='coef'?'Par coefficient':'Personnalisé'}</p></article><article class="setting-card"><h3>🌍 Langue</h3><select class="field" onchange="toast('Langue enregistrée')"><option>Français</option><option>English</option><option>Español</option></select></article><article class="setting-card" onclick="profileModal()"><h3>👤 Informations personnelles</h3><p>${state.user.firstName} ${state.user.lastName} · ${state.user.className}</p></article><article class="setting-card"><h3>☁️ Compte</h3><p>alex.martin@exemple.fr</p><button class="btn danger" onclick="toast('Déconnexion disponible avec l’authentification réelle')">Se déconnecter</button></article></div>`,'Paramètres',true)}
function orderModal(){modal(`<h2>Ordre des matières</h2><div class="field"><label><input type="radio" name="ord" value="alpha" ${state.order==='alpha'?'checked':''}> Ordre alphabétique</label><label><input type="radio" name="ord" value="coef" ${state.order==='coef'?'checked':''}> Ordre par coefficient</label><label><input type="radio" name="ord" value="custom" ${state.order==='custom'?'checked':''}> Ordre personnalisé</label></div><div class="reorder">${state.subjects.map((s,i)=>`<div class="drag-item row"><span>${i+1}. ${s.name}</span><span class="spacer"></span><button class="tiny-action" onclick="moveSubject(${i},-1)">↑</button><button class="tiny-action" onclick="moveSubject(${i},1)">↓</button></div>`).join('')}</div><div class="form-actions"><button class="btn primary" onclick="saveOrder()">Valider</button></div>`)}function moveSubject(i,d){let j=i+d;if(j<0||j>=state.subjects.length)return;[state.subjects[i],state.subjects[j]]=[state.subjects[j],state.subjects[i]];closeModal();orderModal()}function saveOrder(){state.order=document.querySelector('input[name=ord]:checked').value;save();closeModal();render()}
function profileModal(){let u=state.user;modal(`<h2>Informations personnelles</h2><form id="profileForm"><div class="field"><label>Nom</label><input name="lastName" value="${u.lastName}"></div><div class="field"><label>Prénom</label><input name="firstName" value="${u.firstName}"></div><div class="field"><label>Date de naissance</label><input type="date" name="birth" value="${u.birth}"></div><div class="field"><label>Classe</label><input name="className" value="${u.className}"></div><div class="field"><label>Petite description personnelle</label><textarea name="bio">${u.bio}</textarea></div><div class="form-actions"><button class="btn" type="button" onclick="closeModal()">Annuler</button><button class="btn primary">Valider</button></div></form>`);$('#profileForm').onsubmit=e=>{e.preventDefault();Object.assign(state.user,Object.fromEntries(new FormData(e.target)));save();closeModal();render()}}
function modal(c){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div class="modal-card">${c}</div></div>`)}function closeModal(){$('#modal')?.remove()}function toast(t){document.body.insertAdjacentHTML('beforeend',`<div class="toast">${t}</div>`);setTimeout(()=>document.querySelector('.toast')?.remove(),2500)}
render();
